use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;

struct Section {
    name: String,
    inherits: Option<String>,
    fields: Vec<(String, String)>,
}

fn quoted_value(raw: &str) -> Result<String, String> {
    let chars: Vec<char> = raw.chars().collect();
    if chars.len() < 2 || chars[0] != '"' || chars[chars.len() - 1] != '"' {
        return Err("value must be enclosed in double quotes".to_string());
    }

    let mut value = String::new();
    let mut escaped = false;
    for ch in &chars[1..chars.len() - 1] {
        if escaped {
            match *ch {
                'n' => value.push('\n'),
                'r' => value.push('\r'),
                't' => value.push('\t'),
                '"' => value.push('"'),
                '\\' => value.push('\\'),
                _ => return Err("unsupported escape in quoted value".to_string()),
            }
            escaped = false;
        } else if *ch == '\\' {
            escaped = true;
        } else if *ch == '"' {
            return Err("unescaped quote in quoted value".to_string());
        } else {
            value.push(*ch);
        }
    }
    if escaped {
        return Err("unterminated escape in quoted value".to_string());
    }
    Ok(value)
}

fn parse_file(path: &str) -> Result<Vec<Section>, String> {
    let source = fs::read_to_string(path)
        .map_err(|error| format!("cannot read '{}': {}", path, error))?;
    let mut sections = Vec::new();
    let mut indexes = HashMap::new();
    let mut current = None;

    for (line_index, raw_line) in source.lines().enumerate() {
        let line_number = line_index + 1;
        let line = raw_line.trim_end_matches('\r').trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        if line.starts_with('[') {
            if line.len() < 3 || !line.ends_with(']') {
                return Err(format!("malformed section header on line {}", line_number));
            }
            let name = line[1..line.len() - 1].trim();
            if name.is_empty() {
                return Err(format!("empty section name on line {}", line_number));
            }
            if indexes.contains_key(name) {
                return Err(format!("duplicate section '{}'", name));
            }
            let index = sections.len();
            indexes.insert(name.to_string(), index);
            sections.push(Section {
                name: name.to_string(),
                inherits: None,
                fields: Vec::new(),
            });
            current = Some(index);
            continue;
        }

        let section_index = current
            .ok_or_else(|| format!("field before section on line {}", line_number))?;
        let (key_part, value_part) = line
            .split_once('=')
            .ok_or_else(|| format!("malformed field on line {}", line_number))?;
        let key = key_part.trim();
        if key.is_empty() {
            return Err(format!("empty field name on line {}", line_number));
        }
        let value = quoted_value(value_part.trim())
            .map_err(|error| format!("{} on line {}", error, line_number))?;

        let section = &mut sections[section_index];
        if key == "inherits" {
            if section.inherits.is_some() {
                return Err(format!(
                    "duplicate field 'inherits' in section '{}'",
                    section.name
                ));
            }
            section.inherits = Some(value);
        } else {
            if section.fields.iter().any(|(field, _)| field == key) {
                return Err(format!(
                    "duplicate field '{}' in section '{}'",
                    key, section.name
                ));
            }
            section.fields.push((key.to_string(), value));
        }
    }

    Ok(sections)
}

fn resolve(
    index: usize,
    sections: &[Section],
    indexes: &HashMap<String, usize>,
    states: &mut [u8],
) -> Result<Vec<(String, String)>, String> {
    if states[index] == 1 {
        return Err(format!("inheritance cycle involving section '{}'", sections[index].name));
    }
    states[index] = 1;

    let mut fields = Vec::new();
    if let Some(parent_name) = sections[index].inherits.as_ref() {
        let parent_index = indexes
            .get(parent_name)
            .copied()
            .ok_or_else(|| {
                format!(
                    "section '{}' inherits unknown section '{}'",
                    sections[index].name, parent_name
                )
            })?;
        fields = resolve(parent_index, sections, indexes, states)?;
    }

    for (key, value) in &sections[index].fields {
        if let Some((_, existing)) = fields.iter_mut().find(|(field, _)| field == key) {
            *existing = value.clone();
        } else {
            fields.push((key.clone(), value.clone()));
        }
    }

    states[index] = 2;
    Ok(fields)
}

fn run(path: &str) -> Result<String, String> {
    let sections = parse_file(path)?;
    let indexes: HashMap<String, usize> = sections
        .iter()
        .enumerate()
        .map(|(index, section)| (section.name.clone(), index))
        .collect();
    let mut states = vec![0u8; sections.len()];
    let mut output = String::new();

    for index in 0..sections.len() {
        let fields = resolve(index, &sections, &indexes, &mut states)?;
        for (key, value) in fields {
            output.push_str(&sections[index].name);
            output.push('.');
            output.push_str(&key);
            output.push('=');
            output.push_str(&value);
            output.push('\n');
        }
    }
    Ok(output)
}

fn main() {
    let mut arguments = env::args();
    let _program = arguments.next();
    let path = match arguments.next() {
        Some(path) => path,
        None => {
            eprintln!("missing records.cfg path");
            process::exit(1);
        }
    };

    match run(&path) {
        Ok(output) => print!("{}", output),
        Err(error) => {
            eprintln!("{}", error);
            process::exit(1);
        }
    }
}
